from .audit import event


class TransferService:
    def __init__(self, ledger):
        self.ledger = ledger

    def transfer(self, source, target, amount, inject=None):
        balances = self.ledger.balances
        if source not in balances or target not in balances:
            raise KeyError('unknown account')
        if source == target or type(amount) is not int or amount <= 0:
            raise ValueError('invalid transfer')
        if balances[source] < amount:
            raise ValueError('insufficient funds')

        # Prepare the transfer without touching the ledger: the new balances
        # and the audit event are computed first and committed together only
        # after every injected phase has completed, so a fault at any phase
        # leaves balances and audit log exactly as before.
        new_balances = {
            source: balances[source] - amount,
            target: balances[target] + amount,
        }
        audit_event = event(source, target, amount)

        if inject is not None:
            inject('after_debit')
            inject('after_credit')
            inject('before_audit')

        self._commit(new_balances, audit_event)
        return True

    def _commit(self, new_balances, audit_event):
        # Apply the balance changes and the audit record in one commit step.
        self.ledger.balances.update(new_balances)
        self.ledger.audit.append(audit_event)
